const data=window.PORTFOLIO;
const element=(tag,cls,text)=>{const e=document.createElement(tag);if(cls)e.className=cls;if(text)e.textContent=text;return e;};
function tags(items){const div=element('div','tags');items.forEach(i=>div.append(element('span','tag',i)));return div;}
function media(item,cls,index){const box=element(item.image?'button':'div',cls+(item.image?' image-button':''));if(item.image){const img=element('img');img.src=item.image;img.alt=item.title;img.loading='lazy';box.append(img);box.setAttribute('aria-label','View '+item.title);box.onclick=()=>{document.querySelector('#full-image').src=item.image;document.querySelector('#full-image').alt=item.title;document.querySelector('#image-caption').textContent=item.title;document.querySelector('#image-dialog').showModal();};img.onerror=()=>{box.replaceChildren(element('span','placeholder-title','Image unavailable'));box.disabled=true;};}else{box.append(element('span','placeholder-icon',cls==='project-media'?'</>':'▧'),element('span','placeholder-title',cls==='project-media'?'Project image coming soon':'Certificate image placeholder'),element('span','placeholder-sub',cls==='project-media'?'IMAGE TO BE ADDED':'TO BE ADDED'));}if(cls==='project-media')box.append(element('span','media-no','0'+(index+1)));return box;}
data.skills.forEach(s=>{const card=element('div','skill');card.append(element('h3','',s.title),tags(s.items));document.querySelector('#skills').append(card);});
data.projects.forEach((p,i)=>{const card=element('article','project');const list=element('ul');p.contributions.forEach(c=>list.append(element('li','',c)));card.append(media(p,'project-media',i),element('p','project-meta',p.category),element('h3','',p.title),tags(p.technologies),list);document.querySelector('#project-grid').append(card);});
data.certificates.forEach((c,i)=>{const card=element('article','certificate');card.append(media(c,'certificate-media',i),element('h3','',c.title),element('p','',c.issuer+' · '+c.date));if(!c.verified)card.append(element('span','placeholder-badge','PLACEHOLDER / DETAILS TO BE ADDED'));document.querySelector('#certificate-grid').append(card);});
if(data.personal.github){const a=element('a','text-link','GitHub ↗');a.href=data.personal.github;a.target='_blank';a.rel='noopener noreferrer';document.querySelector('.contact-bottom').prepend(a);}
const bot=window.createPortfolioAssistant(data);const messages=document.querySelector('#messages');
function message(text,user=false,source=''){const el=element('div','message'+(user?' user':''),text);if(source)el.append(element('small','',source));messages.append(el);messages.scrollTop=messages.scrollHeight;}
function reset(){messages.replaceChildren();message('Ask me about Carl’s skills, education, projects, or personal interests. What would you like to know?');}
function ask(q){q=q.trim();if(!q)return;message(q,true);const result=bot.answer(q);message(result.text,false,result.source||'');}
document.querySelector('#chat-form').onsubmit=e=>{e.preventDefault();const input=document.querySelector('#question');ask(input.value);input.value='';input.focus();};
document.querySelectorAll('[data-question]').forEach(b=>b.onclick=()=>ask(b.dataset.question));document.querySelector('#clear-chat').onclick=reset;reset();
document.querySelector('#close-image').onclick=()=>document.querySelector('#image-dialog').close();
const reduced=matchMedia('(prefers-reduced-motion: reduce)'),fine=matchMedia('(pointer: fine)');let trailEnabled=!reduced.matches&&fine.matches,last=0;const trail=document.querySelector('#trail-layer'),toggle=document.querySelector('#trail-toggle');
function syncTrail(){toggle.textContent='Cursor trail: '+(trailEnabled?'on':'off');toggle.setAttribute('aria-pressed',String(trailEnabled));if(!trailEnabled)trail.replaceChildren();}syncTrail();toggle.onclick=()=>{trailEnabled=!trailEnabled;syncTrail();};reduced.addEventListener('change',()=>{trailEnabled=!reduced.matches&&fine.matches;syncTrail();});
const words=['const','{ }','build()','return','<div>','await','let','=>','0101','function','</>','new','[ ]','create()'];
document.addEventListener('pointermove',e=>{if(!trailEnabled||reduced.matches||e.pointerType!=='mouse'||e.timeStamp-last<85||e.target.closest('input,button,a,.chat'))return;last=e.timeStamp;const word=element('span','trail-word',words[Math.floor(Math.random()*words.length)]);word.style.left=(e.clientX+12)+'px';word.style.top=(e.clientY+10)+'px';trail.append(word);setTimeout(()=>word.remove(),1250);});
